<?php $title='Tasks';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>Tasks</h1><p>Work generated by services or created manually.</p></div><a class="primary" href="<?=route('task.create')?>">+ New Task</a></div><div class="panel table-wrap"><table><thead><tr><th>Task</th><th>Client</th><th>Assigned</th><th>Priority</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['full_name']??'')?></td><td><?=e($r['assigned_name']??'')?></td><td><?=e($r['priority'])?></td><td><?=e($r['due_at'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']!=='completed'):?><a href="<?=route('task.complete',['id'=>$r['id']])?>" data-confirm="Mark this task complete?">Complete</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../layouts/footer.php';?>
